select is(encode(desmoslock_v2.internal_student_evidence_content_bytes(v.vector->>'apiOrigin',v.vector->>'originalKeyThumbprint',
  v.vector->'scope',v.vector->'originBuild',f.fact),'hex'),v.vector->'contentBytesHex'->>(f.ordinality::integer-1),
  v.name || ' SQL fact canonical bytes ' || f.ordinality)
from evidence_vectors v cross join lateral jsonb_array_elements(v.vector->'facts') with ordinality f(fact,ordinality);
select is(desmoslock_v2.internal_student_evidence_content_digest(v.vector->>'apiOrigin',v.vector->>'originalKeyThumbprint',
  v.vector->'scope',v.vector->'originBuild',f.fact),v.vector->'contentDigests'->>(f.ordinality::integer-1),
  v.name || ' SQL fact digest ' || f.ordinality)
from evidence_vectors v cross join lateral jsonb_array_elements(v.vector->'facts') with ordinality f(fact,ordinality);
select is(encode(desmoslock_v2.internal_student_evidence_batch_bytes(vector->>'apiOrigin',vector->>'originalKeyThumbprint',
  vector->'scope',vector->'originBuild',vector->'facts'),'hex'),vector->>'batchBytesHex',name || ' SQL batch canonical bytes') from evidence_vectors;
select is(desmoslock_v2.internal_student_evidence_batch_digest(vector->>'apiOrigin',vector->>'originalKeyThumbprint',
  vector->'scope',vector->'originBuild',vector->'facts'),vector->>'batchDigest',name || ' SQL batch digest') from evidence_vectors;

select ok(not has_table_privilege(r.role,t.name,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),r.role || ' has no direct ' || t.name || ' access')
from (values ('anon'),('authenticated'),('service_role')) r(role)
cross join (values ('desmoslock_v2.student_device_proof_state'),('desmoslock_v2.student_protection_events')) t(name);
select ok(relrowsecurity,'RLS enabled for ' || relname) from pg_class where oid in
  ('desmoslock_v2.student_device_proof_state'::regclass,'desmoslock_v2.student_protection_events'::regclass);
select ok(has_function_privilege('service_role',
  'desmoslock_v2.commit_student_protection_evidence(text,uuid,uuid,uuid,uuid,bigint,jsonb,jsonb,text,text,bigint)','EXECUTE'),'service can commit verified evidence');
select ok(not has_function_privilege('authenticated',
  'desmoslock_v2.commit_student_protection_evidence(text,uuid,uuid,uuid,uuid,bigint,jsonb,jsonb,text,text,bigint)','EXECUTE'),'staff cannot assert device proof');
select ok(not has_function_privilege('service_role',
  'desmoslock_v2.current_student_protection_events(uuid,uuid,uuid,text,uuid)','EXECUTE'),'service cannot impersonate live staff history');
select ok(has_function_privilege('authenticated',
  'desmoslock_v2.current_student_protection_events(uuid,uuid,uuid,text,uuid)','EXECUTE'),'authenticated staff enters live authorization gate');
select is((select count(*) from desmoslock_v2.student_device_proof_state),0::bigint,'pristine proof state is empty');
select is((select count(*) from desmoslock_v2.student_protection_events),0::bigint,'pristine reports are empty');

select pg_temp.student_claims(2,'aal1');
insert into student_results select 'code',to_jsonb(r) from desmoslock_v2.issue_test_join_code(
  '16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',2,
  '46000000-0000-4000-8000-000000000001',repeat('1',64)) r;
insert into student_results select 'joined',to_jsonb(pg_temp.student_join('initial',
  '56000000-0000-4000-8000-000000000001','66000000-0000-4000-8000-000000000001',repeat('A',43),
  repeat('1',64),repeat('2',64),repeat('3',64)));
select is((select result->>'code' from student_results where label='joined'),'ok','real initial join is accepted');
select is((select count(*) from desmoslock_v2.student_device_proof_state),1::bigint,'join atomically creates common proof state');
create function pg_temp.evidence_scope() returns jsonb language sql as $$
  select jsonb_build_object('schoolId',result->>'school_id','testId',result->>'test_id',
    'studentSessionId',result->>'student_session_id','deviceSessionId',result->>'device_session_id','epoch',(result->>'epoch')::bigint)
  from student_results where label='joined';
$$;
create function pg_temp.evidence_fact(sequence bigint, slot text default 'engaging', attempt integer default 1, scope jsonb default null)
returns jsonb language sql as $$
  select jsonb_build_object('sequence',$1,'eventId','96000000-0000-4000-8000-' || lpad($1::text,12,'0'),
    'attemptId','97000000-0000-4000-8000-' || lpad($3::text,12,'0'),'scope',coalesce($4,pg_temp.evidence_scope()),
    'policyVersion',1,'slot',$2,'phase',case $2 when 'engaging' then 'engaging' when 'failure' then 'failed' else 'ended' end,
    'nativeEvent',null,'nativeSequence',null,
    'categories',jsonb_build_object('aac',jsonb_build_object('status','pending','code','awaiting_native_begin'),
      'shortcuts',jsonb_build_object('status',case when $2='failure' then 'unavailable' else 'confirmed' end,
        'code',case when $2='failure' then 'emergency_shortcut_unavailable' else 'none' end),
      'applications',jsonb_build_object('status','confirmed','code','none'),
      'persistence',jsonb_build_object('status','confirmed','code','none'),
      'windowNetwork',jsonb_build_object('status','confirmed','code','none')),
    'cause',case when $2='failure' then 'shortcut_unavailable' else 'none' end);
$$;
create function pg_temp.evidence_ingest(facts jsonb, counter bigint, key text default repeat('A',43), origin jsonb default '{"kind":"unverified_build"}')
returns jsonb language plpgsql as $$
declare scope jsonb := $1->0->'scope'; result desmoslock_v2.student_evidence_row;
begin
  select * into result from desmoslock_v2.commit_student_protection_evidence('http://127.0.0.1:54321',
    (scope->>'schoolId')::uuid,(scope->>'testId')::uuid,(scope->>'studentSessionId')::uuid,(scope->>'deviceSessionId')::uuid,(scope->>'epoch')::bigint,
    $4,$1,desmoslock_v2.internal_student_evidence_batch_digest('http://127.0.0.1:54321',desmoslock_v2.internal_student_key_thumbprint($3),scope,$4,$1),$3,$2);
  return to_jsonb(result);
end;
$$;
create function pg_temp.evidence_snapshot() returns jsonb language sql as $$
  select jsonb_build_object('domain',pg_temp.student_snapshot(),
    'proof',(select jsonb_agg(to_jsonb(p) || jsonb_build_object('tuple',p.ctid::text) order by p.test_id,p.device_session_id) from desmoslock_v2.student_device_proof_state p),
    'events',(select jsonb_agg(to_jsonb(e) || jsonb_build_object('tuple',e.ctid::text) order by e.event_id) from desmoslock_v2.student_protection_events e));
$$;
-- Privileged synthetic clock aging preserves monotonic counters and the active
-- mirror. It is not a production allowance-reset API.
create function pg_temp.evidence_age_window() returns void language plpgsql as $$
begin
  update desmoslock_v2.student_device_proof_state p set last_accepted_proof_counter=p.last_accepted_proof_counter+1,
    evidence_accepted_at=array[clock_timestamp()-interval '61 seconds'];
  update desmoslock_v2.student_sessions s set last_accepted_proof_counter=p.last_accepted_proof_counter
    from desmoslock_v2.student_device_proof_state p where s.state='active' and s.test_id=p.test_id and s.device_session_id=p.device_session_id;
end;
$$;

