-- Rejection coverage exercises actual SQL finite validators, not a shadow
-- parser; malformed calls retain the same digest/counter denial boundary.
select ok(desmoslock_v2.internal_evidence_build_array(jsonb_set(v.vector->'originBuild',array['identity',field.name],
  to_jsonb(repeat('0',case when field.name in ('sourceCommit','sourceTree') then 40 else 64 end)))) is null,
  'SQL rejects zero build hash ' || field.name)
from evidence_vectors v cross join (values ('sourceCommit'),('sourceTree'),('packageLockSha256'),('buildId')) field(name)
where v.name='known_maximum';
select ok(desmoslock_v2.internal_evidence_fact_array(pg_temp.evidence_fact(1) || '{"rawProcessList":[]}') is null,'arbitrary report payload rejected');
select ok(desmoslock_v2.internal_evidence_fact_array(jsonb_set(pg_temp.evidence_fact(1),'{sequence}','9007199254740992')) is null,'unsafe fact integer rejected');
select ok(desmoslock_v2.internal_evidence_fact_array(jsonb_set(pg_temp.evidence_fact(1),'{sequence}','1.5')) is null,'fractional fact integer rejected');
select ok(desmoslock_v2.internal_evidence_fact_array(jsonb_set(pg_temp.evidence_fact(1),'{eventId}','"96000000-0000-5000-8000-000000000001"')) is null,'fact ID requires UUIDv4');
select ok(desmoslock_v2.internal_evidence_fact_array(jsonb_set(pg_temp.evidence_fact(1),'{nativeEvent}','"did_begin"')) is null,'native observation cannot occupy engaging slot');
