-- A complete 32-attempt/256-fact fixture uses the independent finite eight-slot
-- vector. Only capacity setup writes reports directly; admission is real and
-- all capacity/duplicate decisions below call production commit.
insert into student_results select 'capacity-joined',to_jsonb(pg_temp.student_join('initial',
  '56000000-0000-4000-8000-000000000004','66000000-0000-4000-8000-000000000004',repeat('D',42)||'A',
  repeat('1',64),repeat('a',64),repeat('b',64)));
select is((select result->>'code' from student_results where label='capacity-joined'),'ok','independent capacity binding admitted');
create temporary table capacity_facts (fact jsonb not null);
insert into capacity_facts
select f.fact || jsonb_build_object('scope',jsonb_build_object('schoolId',r.result->>'school_id','testId',r.result->>'test_id',
  'studentSessionId',r.result->>'student_session_id','deviceSessionId',r.result->>'device_session_id','epoch',1),
  'sequence',(a.attempt-1)*8+f.ordinality,'eventId','98000000-0000-4000-8000-'||lpad(((a.attempt-1)*8+f.ordinality)::text,12,'0'),
  'attemptId','99000000-0000-4000-8000-'||lpad(a.attempt::text,12,'0'))
from evidence_vectors v cross join lateral jsonb_array_elements(v.vector->'facts') with ordinality f(fact,ordinality)
cross join generate_series(1,32) a(attempt) cross join student_results r
where v.name='known_maximum' and r.label='capacity-joined';
insert into desmoslock_v2.student_protection_events
  (event_id,workspace_id,test_id,student_session_id,device_session_id,epoch,attempt_id,fact_sequence,slot,
    api_origin,key_thumbprint,origin_build,fact,content_digest,received_at)
select (f.fact->>'eventId')::uuid,(f.fact#>>'{scope,schoolId}')::uuid,(f.fact#>>'{scope,testId}')::uuid,
  (f.fact#>>'{scope,studentSessionId}')::uuid,(f.fact#>>'{scope,deviceSessionId}')::uuid,1,(f.fact->>'attemptId')::uuid,
  (f.fact->>'sequence')::bigint,f.fact->>'slot','http://127.0.0.1:54321',
  desmoslock_v2.internal_student_key_thumbprint(repeat('D',42)||'A'),'{"kind":"unverified_build"}',f.fact,
  desmoslock_v2.internal_student_evidence_content_digest('http://127.0.0.1:54321',desmoslock_v2.internal_student_key_thumbprint(repeat('D',42)||'A'),
    f.fact->'scope','{"kind":"unverified_build"}',f.fact),
  '2000-01-01T00:00:00Z'::timestamptz + (f.fact->>'sequence')::bigint * interval '1 microsecond'
from capacity_facts f;
select is((select count(*) from desmoslock_v2.student_protection_events where device_session_id='66000000-0000-4000-8000-000000000004'),256::bigint,'binding fixture reaches exact fact cap');
select is(pg_temp.evidence_ingest((select jsonb_agg(f.fact order by (f.fact->>'sequence')::bigint) from capacity_facts f
  where f.fact->>'attemptId'='99000000-0000-4000-8000-000000000001'),1,repeat('D',42)||'A')->>'code','ok','exact prefix remains recoverable at both storage caps');
