create function pg_temp.evidence_reconnect(counter bigint) returns desmoslock_v2.student_admission_row language plpgsql as $$
declare scope jsonb; request uuid := '76000000-0000-4000-8000-000000000001'; operation text; result desmoslock_v2.student_admission_row;
begin
  scope := pg_temp.evidence_scope() || '{"deviceSessionId":"66000000-0000-4000-8000-000000000003","epoch":3}';
  operation := desmoslock_v2.internal_student_operation_digest(jsonb_build_array('reconnect',request,
    desmoslock_v2.internal_evidence_scope_array(scope),4,repeat('8',64),repeat('c',64),repeat('d',64)));
  select * into result from desmoslock_v2.commit_student_session_reconnect(
    (scope->>'schoolId')::uuid,(scope->>'testId')::uuid,(scope->>'studentSessionId')::uuid,(scope->>'deviceSessionId')::uuid,3,
    request,operation,4,repeat('8',64),repeat('c',64),repeat('d',64),repeat('C',42)||'A',$1);
  return result;
end;
$$;
select is((pg_temp.evidence_reconnect(1)).code,'ok','replacement reconnect advances shared proof counter');
select is((select last_accepted_proof_counter from desmoslock_v2.student_device_proof_state where device_session_id='66000000-0000-4000-8000-000000000003'),1::bigint,'reconnect writes persistent common proof');
select is((pg_temp.evidence_reconnect(1)).code,'student_session_denied','reconnect counter replay denied');
select is((pg_temp.evidence_reconnect(2)).code,'ok','rotation receipt recovery advances common counter without new rotation');
create function pg_temp.evidence_forfeit(counter bigint) returns desmoslock_v2.student_forfeit_row language plpgsql as $$
declare scope jsonb; request uuid := '76000000-0000-4000-8000-000000000002'; operation text; result desmoslock_v2.student_forfeit_row;
begin
  scope := pg_temp.evidence_scope() || '{"deviceSessionId":"66000000-0000-4000-8000-000000000003","epoch":3}';
  operation := desmoslock_v2.internal_student_operation_digest(jsonb_build_array('forfeit',request,
    desmoslock_v2.internal_evidence_scope_array(scope),5,repeat('c',64)));
  select * into result from desmoslock_v2.commit_student_session_forfeit(
    (scope->>'schoolId')::uuid,(scope->>'testId')::uuid,(scope->>'studentSessionId')::uuid,(scope->>'deviceSessionId')::uuid,3,
    request,operation,5,repeat('c',64),repeat('C',42)||'A',$1);
  return result;
end;
$$;
