  'student_session_denied','new engaging insert followed by a global event conflict fails');
select is(pg_temp.evidence_snapshot(),(select result from student_results where label='insert-before-conflict'),
  'later conflict rolls back earlier inserted row and all proof state');
select is((pg_temp.student_read((select (result->>'student_session_id')::uuid from student_results where label='capacity-joined'),
  '66000000-0000-4000-8000-000000000004',1,repeat('a',64),repeat('D',42)||'A',99)).code,
  'student_session_denied','historical ingestion does not relax ended-Test live admission');
select is(pg_temp.evidence_ingest(jsonb_build_array(pg_temp.evidence_fact(1)),9007199254740991)->>'code',
  'ok','largest safe proof counter is accepted without overflow');
insert into student_results values ('maximum-counter',pg_temp.evidence_snapshot());
select is(pg_temp.evidence_ingest(jsonb_build_array(pg_temp.evidence_fact(1)),9007199254740991)->>'code',
  'student_session_denied','maximum accepted counter cannot replay');
select is(pg_temp.evidence_ingest(jsonb_build_array(pg_temp.evidence_fact(1)),9007199254740992)->>'code',
  'student_session_denied','counter beyond safe integer ceiling is denied');
select is(pg_temp.evidence_snapshot(),(select result from student_results where label='maximum-counter'),
  'overflow and maximum replay preserve counter, allowance and original receipts');

-- Live staff revocation uses the actual administrative RPC; stale captured
-- account requests receive no report after Membership changes.
select pg_temp.student_claims(1,'aal2');
select is((select code from desmoslock_v2.revoke_membership('16000000-0000-4000-8000-000000000001',
  '26000000-0000-4000-8000-000000000002',1)),'membership_revoked','Owner revokes reporting Teacher');
select pg_temp.student_claims(2,'aal1');
select is((select code from desmoslock_v2.current_student_protection_events(
  '16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',(pg_temp.evidence_scope()->>'studentSessionId')::uuid,null,null)),
  'membership_inactive','revoked Teacher history cannot survive live Membership gate');
select ok((select evidence_summary is null from desmoslock_v2.current_test_student_sessions(
  '16000000-0000-4000-8000-000000000001','36000000-0000-4000-8000-000000000001',null,null)),
  'revoked staff list discloses no summary');

select * from finish();
rollback;
